package com.example.lms.quiz;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*;
@Entity public class QuizQuestion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(optional=false) private Quiz quiz; @Column(nullable=false) private String questionText; @Column(nullable=false) private String optionA; @Column(nullable=false) private String optionB; @Column(nullable=false) private String optionC; @Column(nullable=false) private String optionD; @JsonIgnore @Column(nullable=false) private int correctOption; private String solution; protected QuizQuestion(){} public QuizQuestion(String q,String a,String b,String c,String d,int correct,String solution){questionText=q;optionA=a;optionB=b;optionC=c;optionD=d;correctOption=correct;this.solution=solution;} public Long getId(){return id;} public String getQuestionText(){return questionText;} public String getOptionA(){return optionA;} public String getOptionB(){return optionB;} public String getOptionC(){return optionC;} public String getOptionD(){return optionD;} public int correct(){return correctOption;} @JsonIgnore public String getSolution(){return solution;} void setQuiz(Quiz q){quiz=q;} }
